<script setup lang="ts">
import type {CommunityEntry} from '~/types/community'
const api=useRequestFetch(),page=ref(1),tab=ref('timeline')
const {data,error,refresh}=await useAsyncData(()=>`community:${page.value}`,()=>api<{items:CommunityEntry[],total:number}>(`/api/community-entries?page=${page.value}`))
useSeoMeta({title:'社团动态与相册 · 澄之响',description:'在一次次相遇中，留下澄之响共同的故事。'})
</script>
<template><div class="experience-page"><header class="experience-heading"><div><p class="eyebrow">OUR COLLECTIVE MEMORY</p><h1>把相遇，留成故事<span>。</span></h1><p>社团动态、线下活动和共同的相册。</p></div><NuxtLink to="/ranking" class="text-link">回顾十二橙器<AppIcon name="arrowUpRight" :size="16" /></NuxtLink></header><nav class="experience-tabs" aria-label="社团档案展示方式"><button :aria-pressed="tab==='timeline'" @click="tab='timeline'">社团时间线</button><button :aria-pressed="tab==='gallery'" @click="tab='gallery'">活动相册</button></nav><div v-if="error" class="empty-state" role="alert"><p>社团动态暂时加载失败。</p><button class="button secondary" @click="refresh()">重试</button></div><div v-else :class="tab==='timeline'?'community-timeline':'community-albums'"><article v-for="item in (data?.items||[]).filter(item=>tab==='timeline'||item.assetIds.length)" :key="item.id" class="experience-card timeline-entry"><time>{{ item.date }}</time><span class="small-kicker">{{ item.kind==='activity'?'社团活动':'社团动态' }}</span><h2>{{ item.title }}</h2><p class="entry-copy">{{ item.content }}</p><MediaGallery :asset-ids="item.assetIds" :label="item.title" /><small>{{ item.author }}</small></article><p v-if="!data?.items.length" class="empty-state">下一次相遇，等我们一起写下。活动安排由管理员公布。</p><p v-else-if="tab==='gallery'&&!data.items.some(item=>item.assetIds.length)" class="empty-state">本页动态暂无照片，可继续翻页查看。</p></div><div class="page-controls"><button :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="page*12>=(data?.total||0)" @click="page++">下一页</button></div></div></template>
